import { motion } from 'framer-motion';
import {
  ExternalLink,
  Video,
  Mic,
  Presentation,
  Monitor,
  Lightbulb,
  LineChart,
  Building,
  FileText,
  type LucideIcon,
} from 'lucide-react';
import { createElement } from 'react';
import { Link } from 'react-router-dom';

import { Article } from '../../types/common';
import { optimizeImageUrl } from '../../utils/imageUrl';
import { scrollToTop } from '../../utils/scroll';

function getArticleIcon(type: string): LucideIcon {
  switch (type.toLowerCase()) {
    case 'video':
      return Video;
    case 'podcast':
      return Mic;
    case 'presentation':
      return Presentation;
    case 'event':
      return Monitor;
    case 'insight':
      return Lightbulb;
    case 'case-study':
      return LineChart;
    case 'news':
      return Building;
    default:
      return FileText;
  }
}

interface ArticleCardProps {
  article: Article;
}

export default function ArticleCard({ article }: ArticleCardProps) {
  const formattedDate = article.date
    ? new Date(article.date).toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'long',
      })
    : null;

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
      className="group bg-white dark:bg-neutral-dark rounded-xl overflow-hidden shadow-lg hover:shadow-xl transition-all h-[24rem]"
    >
      <Link
        to={`/articles/${article.id}`}
        className="flex flex-col h-full"
        onClick={scrollToTop}
        aria-label={`Read full article: ${article.title} - Published in ${article.publication} on ${formattedDate}`}
      >
        <div className="relative aspect-video overflow-hidden">
          {article.image && (
            <img
              src={optimizeImageUrl(article.image, 800)}
              alt={article.title}
              className="w-full h-full object-cover transform group-hover:scale-110 transition-transform duration-500"
              width={800}
              height={450}
              loading="lazy"
              decoding="async"
            />
          )}
          <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
          <div className="absolute bottom-4 right-4 bg-white dark:bg-neutral-dark rounded-full p-2 opacity-0 group-hover:opacity-100 transform group-hover:translate-y-0 translate-y-4 transition-all duration-300">
            <ExternalLink
              className="w-5 h-5 text-primary dark:text-primary-light"
              aria-hidden="true"
            />
          </div>
        </div>

        <div className="flex-1 p-6 flex flex-col">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
              {createElement(getArticleIcon(article.type), {
                className: 'w-5 h-5 text-primary dark:text-primary-light',
                'aria-hidden': true,
              })}
              <span className="text-sm font-medium text-primary dark:text-primary-light">
                {article.publication}
              </span>
            </div>
            {formattedDate && (
              <time
                dateTime={article.date}
                className="text-sm text-neutral-dark/70 dark:text-white/70"
              >
                {formattedDate}
              </time>
            )}
          </div>

          <div className="flex-1 flex flex-col">
            <h3 className="text-xl font-bold text-neutral-dark dark:text-white mb-2 group-hover:text-primary dark:group-hover:text-primary-light transition-colors line-clamp-2">
              {article.title}
            </h3>

            <p className="text-neutral-dark/70 dark:text-white/70 line-clamp-3">
              {article.headline || article.description}
            </p>
          </div>
        </div>
      </Link>
    </motion.div>
  );
}
